{"command": "cd . && timeout 75 python3 - <<'PYEOF'
import numpy as np, importlib.util, json, time
spec = importlib.util.spec_from_file_location("mqc", "morphospace_q_conservation.py")
mqc = importlib.util.module_from_spec(spec); spec.loader.exec_module(mqc)
t0 = time.time()

def d2(n_pts, series_fn, m=6, tau=None, n_r=25, max_pts=3000):
    s = np.asarray(series_fn(n_pts), dtype=float)
    if s.ndim > 1: s = s[:, 0]
    mqc.rng = np.random.default_rng(0)
    return mqc.correlation_dimension(s, m=m, tau=tau, n_r=n_r, max_pts=max_pts)

results = {}
checks = [
    ("lorenz35", lambda n: mqc.lorenz_attractor(rho=35.0, T=n*0.01, transient=200.0), [4000, 8000, 16000]),
    ("henon14",  lambda n: mqc.henon_orbit(1.4, 0.3, n=n)[0],                        [4000, 8000, 16000]),
    ("rule110",  lambda n: mqc.rule110_evolve(n_cells=400, steps=n, init='random', seed=0)[:2000, 200], [2000, 4000, 4000]),
]
for name, fn, sizes in checks:
    row = []
    for n in sizes:
        try:
            row.append(float(d2(n, fn)))
        except Exception as e:
            row.append(None)
    results[name] = {"sizes": sizes, "d2": row}
    print(f"{name}: sizes={sizes} D2={['%.3f'%v if v else 'FAIL' for v in row]}")

# Convergence metric: |D2(default) - D2(double)| relative to default
print("\n--- Convergence (halved vs default) ---")
conv = {}
for name, r in results.items():
    valid = [(n,v) for n,v in zip(r['sizes'], r['d2']) if v is not None and v > 0]
    if len(valid) >= 2:
        (n1,v1),(n2,v2) = valid[0], valid[-1]
        drift = abs(v2-v1)/max(v1,1e-9)
        conv[name] = dict(n_small=n1, d2_small=v1, n_large=n2, d2_large=v2, rel_drift=float(drift))
        print(f"  {name}: D2({n1})={v1:.3f} -> D2({n2})={v2:.3f}  rel_drift={drift*100:.1f}%")

json.dump({"results": results, "convergence": conv}, open('convergence_check.json','w'), indent=1, default=float)
print(f"\nsaved convergence_check.json ({time.time()-t0:.0f}s)")
PYEOF
echo "EXIT=$?""}

